// Realistic mutations of the engine: each one introduces ONE plausible fault into a throwaway copy, and the targeted tests
// must fail FOR THE RIGHT REASON (the test or scenario named by `expected`). R01–R18: 1st cold review (R05 includes its
// complement M05b); C01–C19, C09b, C11b: counter-review; X-…: survivors of the targeted review; T-…: 3rd round, one per
// fix; S…: native DBOS functions (ROADMAP §8.14, S1–S6). Adapted to the current code; `node tests/mutations/launch.ts`.
// Removed with their mechanism (simplification §8.14): C04 (W2's task-finished message → native status), X-beta
// (check of the children on wake-up → native wait), T-G2 (W2 of another version in the queue → constant version),
// T-M1 (suffix `cycle-<id>.<n>` → stable id, rewind), T-M2a / T-M2b (copying and setting aside messages →
// asked again, S5), T-late (race between message and operation status → no more message). ID-…: identity of people
// (I0, ADR-017): token, hats, four eyes, idempotence per person, binding (issuer, subject), database. A0-…: fixed image
// of the tools (A-R0): forbidden paths, Dockerfile ownership, fixed Dockerfile, CI, guard-rails. AR4-…: reviewers
// Bash,Read without permission, overlap Read only (A-R4, ADR-020). AR5-…: caps per role and model table (A-R5).
// G4-…: core reference (vendor/ and node_modules/ forbidden, registry-only dependencies, lockfile resolution).
export interface Mutation {
  id: string;
  fault: string;
  file: string;
  /** Exact text replaced (must appear only once). Several pairs = a single fault in several places. */
  replacements: [before: string, after: string][];
  /** Test commands run in the copy; the mutation is killed if one of them fails with `expected` in its output. */
  tests: string[];
  expected: RegExp;
  /** Timeout of a command (default 15 min): a fault that makes it wait forever is killed by this timeout. */
  timeoutMs?: number;
}

const CUKE = './node_modules/.bin/cucumber-js';
/** Cucumber scenario named in the "Failed scenarios" list. */
const scenario = (name: string) => new RegExp(`\\d+\\) ${name}`);
/** Failing node:test test. */
const testNode = (name: string) => new RegExp(`✖ ${name}`);
const ROB = (reason: string) => `node --test --test-name-pattern "${reason}" tests/robustness.test.ts`;
const REPL = (reason: string) => `node --test --test-name-pattern "${reason}" tests/replacement.test.ts`;
const MON = (reason: string) => `node --test --test-name-pattern "${reason}" tests/monitoring.test.ts`;
