const FORGE = (reason: string) => `node --test --test-name-pattern "${reason}" tests/gitea-forge.test.ts`;
const SSHD = (reason: string) => `node --test --test-name-pattern "${reason}" tests/ssh-deployer.test.ts`;
const MAILS = (reason: string) => `node --test --test-name-pattern "${reason}" tests/mails.test.ts`;
const CLAUDE = (reason: string) => `node --test --test-name-pattern "${reason}" tests/claude-engine.test.ts`;
const OUTPUT = (reason: string) => `node --test --test-name-pattern "${reason}" tests/claude-output.test.ts`;
